import { useState } from "react";
import "./Services.css";

function Services() {
  const [selectedService, setSelectedService] = useState(null);

  const services = [
    {
      name: "2-Wheeler Driving Training",
      details: "Price: ₹5000\nDuration: 10 days\nDocuments Required: ID proof, Address proof"
    },
    {
      name: "4-Wheeler Driving Training",
      details: "Price: ₹8000\nDuration: 15 days\nDocuments Required: ID proof, Address proof"
    },
    {
      name: "Fast Tag",
      details: "Price: ₹500\nDuration: 1 day\nDocuments Required: Vehicle RC, ID proof"
    },
    {
      name: "License Renewal",
      details: "Price: ₹300\nDuration: 2 days\nDocuments Required: Old License, ID proof"
    },
    {
      name: "Vehicle Passing",
      details: "Price: ₹1000\nDuration: 1 day\nDocuments Required: Vehicle documents"
    },
    {
      name: "Other Driving Courses",
      details: "Contact us for details on other courses."
    },
  ];

  return (
    <div className="services">
      <h2>Our Services</h2>
      <div className="service-cards">
        {services.map((service, index) => (
          <div className="card" key={index}>
            {service.name}
            <br />
            <button
              style={{ marginTop: "10px", padding: "5px 10px", cursor: "pointer" }}
              onClick={() => setSelectedService(service)}
            >
              View Details
            </button>
          </div>
        ))}
      </div>

      {/* Modal */}
      {selectedService && (
        <div className="modal-overlay" onClick={() => setSelectedService(null)}>
          <div className="modal-content" onClick={(e) => e.stopPropagation()}>
            <h3>{selectedService.name}</h3>
            <pre>{selectedService.details}</pre>
            <button onClick={() => setSelectedService(null)}>Close</button>
          </div>
        </div>
      )}
    </div>
  );
}

export default Services;
